previewCss:
.darma-loader-darma-b8-stacking-blocks { --accent: var(--loader-color, #f59e0b); --accent-2: var(--loader-secondary-color, #ef4444); width: var(--loader-size, 76px); height: var(--loader-size, 76px); position: relative; }
.darma-loader-darma-b8-stacking-blocks span { position: absolute; left: 50%; width: 52%; height: 17%; margin-left: -26%; border-radius: 14%; background: linear-gradient(var(--accent), var(--accent-2)); opacity: 0; animation: darma-loader-darma-b8-stacking-blocks-stack calc(var(--loader-speed, 1s) * 2) ease-in infinite; }
.darma-loader-darma-b8-stacking-blocks span:nth-child(1) { bottom: 8%; animation-delay: 0s; }
.darma-loader-darma-b8-stacking-blocks span:nth-child(2) { bottom: 30%; animation-delay: calc(var(--loader-speed, 1s) * .4); }
.darma-loader-darma-b8-stacking-blocks span:nth-child(3) { bottom: 52%; animation-delay: calc(var(--loader-speed, 1s) * .8); }
.darma-loader-darma-b8-stacking-blocks span:nth-child(4) { bottom: 74%; animation-delay: calc(var(--loader-speed, 1s) * 1.2); }
@keyframes darma-loader-darma-b8-stacking-blocks-stack { 0% { transform: translateY(calc(var(--loader-size, 76px) * -.7)); opacity: 0; } 18% { opacity: 1; } 35%, 92% { transform: translateY(0); opacity: 1; } 100% { transform: translateY(0); opacity: 0; } }

